// ===== selfview Client 加载桩：实现实时从磁盘拉取（经 Host 半 selfview/client-impl RPC）=====
return {
  name: 'selfview-client-loader',
  inject: ['timer'],
  async apply(ctx) {
    const res = await host.call('selfview/client-impl')
    if (!res || !res.ok) throw new Error('selfview/client-impl 拉取失败: ' + String((res && res.error) || '(无响应)'))
    const fn = new Function('ctx', 'React', 'host', 'styles', 'console', 'return (async () => {\n' + res.code + '\n})()')
    const impl = await fn(ctx, React, host, styles, console)
    if (!impl || typeof impl.apply !== 'function') throw new Error('selfview client.js 未返回插件对象')
    return impl.apply(ctx)
  },
}
